/**
 * A depth map that sees through a cut-out's clear texels. Imported only by
 * the code-split chunks that draw one (waterReflectChunk.ts, cloudChunk.ts),
 * never by the main bundle.
 *
 * Babylon's depth renderer tests a cut-out's alpha with the mesh's second UV
 * set whenever the mesh carries one, whatever set the picture is on. A
 * planet's plants and leaves place their picture with the first set and carry
 * the sway's weight and the block light in the second, so without this their
 * cards are written whole: the water behind a plant reads as shallow and
 * foams, and the clouds behind one are hidden.
 */
import { VertexBuffer } from '@babylonjs/core/Buffers/buffer';
import type { DepthRenderer } from '@babylonjs/core/Rendering/depthRenderer';

/**
 * Has the renderer test each cut-out by the UV set its picture is on: while it
 * prepares a mesh whose picture is on the first set, the mesh reports no
 * second, and the shader compiled for it samples the first.
 */
export function testCutoutsByTheirPicture(renderer: DepthRenderer): void {
  const isReady = renderer.isReady.bind(renderer);
  renderer.isReady = (subMesh, useInstances) => {
    const mesh = subMesh.getMesh();
    const picture = subMesh.getMaterial()?.getAlphaTestTexture();
    if (!picture || picture.coordinatesIndex !== 0 || !mesh.isVerticesDataPresent(VertexBuffer.UV2Kind)) return isReady(subMesh, useInstances);
    const own = Object.prototype.hasOwnProperty.call(mesh, 'isVerticesDataPresent');
    const present = mesh.isVerticesDataPresent;
    mesh.isVerticesDataPresent = (kind, ...rest) => kind !== VertexBuffer.UV2Kind && present.call(mesh, kind, ...rest);
    try {
      return isReady(subMesh, useInstances);
    } finally {
      if (own) mesh.isVerticesDataPresent = present;
      else delete (mesh as Partial<typeof mesh>).isVerticesDataPresent;
    }
  };
}
